using OrdersService.Endpoints;using OrdersService.Services;using OrdersService.Clients;using Microsoft.OpenApi.Models;var builder=WebApplication.CreateBuilder(args);builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen(o=>{o.SwaggerDoc("v1",new OpenApiInfo{Title="WAEC Orders Service API",Version="v1"});o.AddSecurityDefinition("Bearer",new OpenApiSecurityScheme{Name="Authorization",Type=SecuritySchemeType.Http,Scheme="bearer",BearerFormat="JWT",In=ParameterLocation.Header});o.AddSecurityRequirement(new OpenApiSecurityRequirement{{new OpenApiSecurityScheme{Reference=new OpenApiReference{Type=ReferenceType.SecurityScheme,Id="Bearer"}},Array.Empty<string>()}});});var catalogUrl=builder.Configuration["Catalog:BaseUrl"]??"http://localhost:8081";builder.Services.AddHttpClient<CatalogClient>(c=>{c.BaseAddress=new Uri(catalogUrl);c.Timeout=TimeSpan.FromSeconds(3);});builder.Services.AddSingleton<OrderStore>();var app=builder.Build();app.UseSwagger();app.UseSwaggerUI(o=>{o.SwaggerEndpoint("/swagger/v1/swagger.json","WAEC Orders Service API V1");o.RoutePrefix="swagger";});app.MapOrderEndpoints();app.Run();